# Enem 2022, 1º dia, caderno azul: Linguagens (questões 1 a 45 do caderno). Duas provas no site:
# enem-2022-linguagens-ingles (1–5 = inglês) e enem-2022-linguagens-espanhol (1–5 = espanhol); 6–45 iguais nas duas.
# Poemas e letras como imagem (versos e direitos): Q5 (Carol Ann Duffy), Q4-es (Mercedes Sosa), Q26 (Chico Buarque).
# Infográficos e quadrinhos como imagem: Q3, Q1-es, Q5-es, Q7, Q9, Q15, Q27, Q32, Q38, Q39, Q44.
import sys, pathlib, re
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent / "tools"))
from enem_aj import carregar_enem, enunciado_enem, paragrafos_enem

D = carregar_enem("enem-2022-dia1-azul")
p = lambda *xs: "".join(f"<p>{x}</p>" for x in xs)
ap = lambda *xs: "".join(f'<p class="apoio">{x}</p>' for x in xs)
fonte = lambda x: f'<p class="fonte">{x}</p>'
tit = lambda x: f'<p class="apoio"><strong>{x}</strong></p>'
P = lambda n: paragrafos_enem(D[n])
T = lambda n, i: P(n)[i][1]


def figs(*pares):
    return [{"arquivo": a, "alt": t} for a, t in pares]


def so_fig(n, arq, alt, i_fonte=None, i_cmd=None):
    """Enunciado = figura + referência + comando (texto do quadro/poema fica na imagem)."""
    par = P(n)
    f = [x for t, x in par if t == "fonte"][-1] if i_fonte is None else T(n, i_fonte)
    cmd = [x for t, x in par if t == "p"][-1] if i_cmd is None else T(n, i_cmd)
    return {"enunciado": "[[fig:1]]" + fonte(f) + p(cmd), "imagens": figs((arq, alt))}


def Q_(n, materia, assunto, expl, tags=(), trocas=(), extra=None, alts=None):
    q = {"materia": materia, "assunto": assunto, "area": "Linguagens", "tags": list(tags), "numeroOriginal": int(str(n).split("-")[0]),
         "enunciado": enunciado_enem(D[n], trocas), "alternativas": dict(alts or D[n]["alternativas"]), "imagens": [], "explicacao": expl}
    if extra: q.update(extra)
    q["alternativas"] = {k: re.sub(r"\s*INSTRUÇÕES PARA A REDAÇÃO.*$", "", v) for k, v in q["alternativas"].items()}
    return q


def corta(s, marca):
    """Separa título colado ao texto: devolve (título, resto) partindo antes de `marca`."""
    i = s.index(marca); return s[:i].strip(), s[i:].strip()


